import{a as t}from"./chunks/theme.wVadnyG9.js";import{_ as a,a as n,c as o,j as s}from"./chunks/framework.DVzkjf-b.js";const m=JSON.parse('{"title":"Teaching AI","description":"Keith Williams’s classroom Studios, teacher starter, and field notes on seeing what a student understands when AI helps build the work.","frontmatter":{"title":"Teaching AI","description":"Keith Williams’s classroom Studios, teacher starter, and field notes on seeing what a student understands when AI helps build the work."},"headers":[],"relativePath":"teaching.md","filePath":"teaching.md"}'),r={name:"teaching.md"};function i(h,e,d,c,l,u){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="teaching-ai" tabindex="-1">Teaching AI <a class="header-anchor" href="#teaching-ai" aria-label="Permalink to &quot;Teaching AI&quot;">​</a></h1><p><strong>AI literacy is not just knowing which button to click.</strong> It&#39;s being able to ask a useful question, make something, and decide whether the result deserves your trust.</p><p>I&#39;ve taught at NJIT for more than two decades. The tools have changed a lot. What still makes teaching worthwhile is seeing someone go from “I don&#39;t know where to start” to “I can figure this out.”</p><h2 id="the-tests-passed-who-won-the-game" tabindex="-1">The Tests Passed. Who Won the Game? <a class="header-anchor" href="#the-tests-passed-who-won-the-game" aria-label="Permalink to &quot;The Tests Passed. Who Won the Game?&quot;">​</a></h2><p>A round of Rock, Paper, Scissors gives me a question to ask after the automated checks pass. What result did the student expect when they played? The feature follows three courses and the choices I make about when an AI coach should speak and when it should wait. <a href="/teaching/when-ai-helps-write-the-code">Read the classroom story</a></p><p><img src="'+t+'" alt="A learner holds a pencil over a blank card beside a worked example."></p><h2 id="build-something-you-can-explain" tabindex="-1">Build something you can explain <a class="header-anchor" href="#build-something-you-can-explain" aria-label="Permalink to &quot;Build something you can explain&quot;">​</a></h2><p>I call these activities <em>Studios</em>. Students try the starter, decide on one change, build it with help, check what happened, and choose what to keep. A short instruction file called <code>AGENTS.md</code> tells the AI how to coach that particular lesson. The decision left to the student changes with the course.</p><table tabindex="0"><thead><tr><th>Studio</th><th>A decision the student owns</th></tr></thead><tbody><tr><td><a href="https://github.com/kaw393939/is117-brand-studio" target="_blank" rel="noreferrer">Brand Studio · Intro to Website Development</a></td><td>Choose an audience for a plain white T-shirt. Show where that choice changed the storefront or its voice.</td></tr><tr><td><a href="https://github.com/kaw393939/is218-rps-starter" target="_blank" rel="noreferrer">Rock, Paper, Scissors · Building Web Applications</a></td><td>Agree on the rule for one round. Explain a test and check the result by playing the game.</td></tr><tr><td><a href="https://github.com/kaw393939/373_hosting" target="_blank" rel="noreferrer">Server Studio · Content Management Systems</a></td><td>Predict how a request will reach a calculator running on the student&#39;s server. Open the public address and check the prediction.</td></tr></tbody></table><p>The <a href="/knowledge-lab/">Knowledge Lab</a> takes the same habit into retrieval. When an AI answers from a collection of documents, can the student find the passage that supports the answer? What happens when the information is missing?</p><h2 id="try-a-studio-in-your-course" tabindex="-1">Try a Studio in your course <a class="header-anchor" href="#try-a-studio-in-your-course" aria-label="Permalink to &quot;Try a Studio in your course&quot;">​</a></h2><p>Start with an assignment you already teach. Choose one moment when you want to hear the learner&#39;s reasoning before the assistant offers an answer. The starter helps you rehearse that exchange and produces a student handout and a set of coaching instructions. The teacher copy contains answers. Share only <code>LESSON.md</code> and <code>AGENTS.md</code> with students. <a href="/downloads/AI-Studio-Starter.zip">Download the teacher Studio starter</a></p><p>For the decisions behind the design, the field notes connect classroom and engineering research to specific choices about hints, evidence, and follow-up questions. <a href="/teaching/studio-field-notes">Read the Studio field notes</a></p><h2 id="learning-beyond-one-assignment" tabindex="-1">Learning beyond one assignment <a class="header-anchor" href="#learning-beyond-one-assignment" aria-label="Permalink to &quot;Learning beyond one assignment&quot;">​</a></h2><p>When AI helps produce an assignment, how do we know what the student can do the next time? That&#39;s the question behind my <a href="/research">research on learning and judgment</a>. The <a href="/ai-careers">AI career field guide</a> gives students a way to choose a project around a responsibility they might encounter at work.</p><p>I also publish the tools behind the teaching. The Educational Design System supplies reusable layouts for course materials. Everyday AI CLI is an alpha toolkit for repeatable AI tasks. <a href="https://kaw393939.github.io/educational-design-system/" target="_blank" rel="noreferrer">Explore the Educational Design System</a> · <a href="https://github.com/kaw393939/everyday-ai-cli" target="_blank" rel="noreferrer">See Everyday AI CLI</a></p>',16)])])}const w=a(r,[["render",i]]);export{m as __pageData,w as default};
